SELECT V.ID, V.YT_VIDEO_ID, V.TITULO, V.PUBLICADO_EM, V.DURACAO_SEG, V.ORIGEM, C.NOME CANAL, V.RESUMO, (SELECT GROUP_CONCAT(CONCAT(T.NOME, '=', IFNULL(VT.MOMENTOS, '')) ORDER BY T.NOME SEPARATOR '|') FROM VIDEO_TEMAS VT JOIN TEMAS T ON T.ID = VT.TEMA_ID WHERE VT.VIDEO_ID = V.ID) TEMAS FROM VIDEOS V JOIN CANAIS C ON C.ID = V.CANAL_ID WHERE V.STATUS = 'ESTUDADO' AND ({{canalId}} = 0 OR V.CANAL_ID = {{canalId}}) AND V.ID > {{depois}} ORDER BY V.ID LIMIT 500